subroutine Fibonacci(n as integer) as integer
    if n <= 1 then
        return n;
    else
        return Fibonacci(n - 1) + Fibonacci(n - 2);
    endIf
endSubroutine

algorithm ComputeFibonacci
    define n as integer;
    read n;
    write Fibonacci(n);
endAlgorithm

