subroutine Power(base as integer, exponent as integer) as integer
    if exponent = 0 then
        return 1;
    else
        return base * Power(base, exponent - 1);
    endIf
endSubroutine

algorithm ComputeFibonacci
    define n as integer;
    read n;
    write Power(n, 2);
endAlgorithm
